74HC595 WRITE, exact sequence. Given out[0..N-1] where out[0] is the chip NEAREST the Teensy:
  uint8_t tx[N];
  for (int i = 0; i < N; i++) tx[i] = out[N-1-i];   // farthest chip's byte goes out FIRST
  SPI1.beginTransaction(SPISettings(4000000, MSBFIRST, SPI_MODE0));
  SPI1.transfer(tx, nullptr, N);
  SPI1.endTransaction();
  delayNanoseconds(200);                 // tsu(SRCLK^ -> RCLK^) needs >= 70 ns at 3.0 V, 85 C
  digitalWriteFast(PIN_RCLK, HIGH);
  delayNanoseconds(200);                 // tw(RCLK high) needs >= 60 ns at 3.0 V, 85 C
  digitalWriteFast(PIN_RCLK, LOW);

74HC165 READ, exact sequence. Fills in[0..M-1] where in[0] is the chip NEAREST the Teensy (opposite convention to the '595 — do not copy-paste the reversal loop):
  digitalWriteFast(PIN_PL_N, LOW);
  delayNanoseconds(200);                 // tw(/PL low) needs >= 32 ns at 3.0 V, 85 C
  digitalWriteFast(PIN_PL_N, HIGH);
  delayNanoseconds(200);                 // covers tsu(/PL high -> CLK^) >= 40 ns AND tPD(/PL -> Q7) = 70 ns
  SPI1.beginTransaction(SPISettings(4000000, MSBFIRST, SPI_MODE0));
  SPI1.transfer(nullptr, in, M);
  SPI1.endTransaction();
